import 'package:flutter/material.dart';
import 'package:rodplayer/core/theme/remux_theme.dart';

class CompatibilityPanel extends StatelessWidget { const CompatibilityPanel({super.key, this.resolution = '4K UHD', this.video = 'HEVC / HDR10+', this.audio = 'Atmos / 7.1', this.directPlay = true}); final String resolution, video, audio; final bool directPlay; @override Widget build(BuildContext context) { final t = Theme.of(context).extension<RemuxTheme>() ?? const RemuxTheme(); return Card(child: Padding(padding: const EdgeInsets.all(16), child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [Text('Playback compatibility', style: TextStyle(color: t.textPrimary, fontWeight: FontWeight.w700)), const SizedBox(height: 12), _row('Video', '$resolution · $video', t), _row('Audio', audio, t), _row('Mode', directPlay ? 'Direct Play' : 'Transcode', t, good: directPlay)]))); } Widget _row(String title, String value, RemuxTheme t, {bool good = false}) => Padding(padding: const EdgeInsets.only(bottom: 7), child: Row(children: [SizedBox(width: 72, child: Text(title, style: TextStyle(color: t.textMuted))), Expanded(child: Text(value, style: TextStyle(color: good ? t.success : t.textSecondary))),])); }
